import React from "react";

const VisualizationButtons = () => (
  <div style={{ marginTop: "25px", display: "flex", gap: "15px" }}>
    <button className="viz-btn">Show Heatmap</button>
    <button className="viz-btn">Show Bar Graph</button>
    <button className="viz-btn">Show Histogram</button>
  </div>
);

export default VisualizationButtons;
